import 'package:chess_core/chess_core.dart';
import 'package:test/test.dart';

import 'training_helpers.dart';

// Expected states were generated by an independent Python implementation of
// docs/plan/04-algorithms.md §5.2-5.3 (SHA-256 fuzz, Dart rounding), not by
// this package. Columns: (phase, reps, ease, intervalDays, dueDay, lapses,
// firstSeenDay) after each run.
typedef Expected = (String, int, double, int, String?, int, String?);

const key = 'a1b2c3d4e5f60718';

final class Step {
  const new(this.run, this.expected);
  final RunRecord run;
  final Expected expected;
}

var _n = 0;

Step _step(
  RunMode mode,
  String day,
  double creditSum, {
  required Expected expect,
  bool completed = true,
  bool deviated = false,
  int graded = 10,
}) => Step(
  scoredRun(
    id: 'r${_n++}',
    lineKey: key,
    mode: mode,
    day: day,
    finishedAt: _n,
    creditSum: creditSum,
    graded: graded,
    completed: completed,
    deviated: deviated,
  ),
  expect,
);

Expected actual(SrsState s) => (
  s.phase.dbValue,
  s.reps,
  s.ease,
  s.intervalDays,
  s.dueDay,
  s.lapses,
  s.firstSeenDay,
);

