        RunMode.srs,
        '2026-01-10',
        10,
        expect: ('review', 1, 2.60, 1, '2026-01-11', 0, '2026-01-10'),
      ),
      _step(
        RunMode.srs,
        '2026-01-11',
        10,
        expect: ('review', 2, 2.70, 4, '2026-01-15', 0, '2026-01-10'),
