  group('SRS scenarios', () {
    scenarios.forEach((name, steps) {
      test(name, () {
        var s = SrsState.initial;
        for (final (i, step) in steps.indexed) {
          s = applySrsRun(s, step.run, key);
          expect(actual(s), step.expected, reason: 'after run ${i + 1}');
        }
        expect(replaySrs(key, [for (final st in steps) st.run]), s);
      });
    });
  });

  test('there are at least 12 scenarios', () {
    expect(scenarios.length, greaterThanOrEqualTo(12));
